    var M = {"john":{"es":"«Yahvé es misericordioso»"},"mary":{"es":"Incierto — «amada», «amargura» o «hija deseada»"},"muhammad":{"es":"«El alabado», «digno de alabanza»"},"alexander":{"es":"«Defensor de los hombres» (aléxō «defender» + anḗr «hombre»)"},"joseph":{"es":"«Él añadirá» / «que Dios añada»"},"michael":{"es":"«¿Quién como Dios?»"},"george":{"es":"«Agricultor, labrador de la tierra» (gē «tierra» + ergon «trabajo»)"},"sophia":{"es":"«Sabiduría»"},"fatima":{"es":"«La que desteta / se abstiene» (raíz f-ṭ-m)"},"ali":{"es":"«Alto, elevado, sublime» (raíz ʿ-l-w)"},"krishna":{"es":"«Oscuro, negro» (por la tez azul-negruzca de la deidad)"},"rama":{"es":"«Agradable, encantador, deleitable» (raíz ram- «agradar, deleitar»)"},"david":{"es":"«Amado»"},"daniel":{"es":"«Dios es mi juez» (dān «juzgar» + ʼēl «Dios»)"},"peter":{"es":"«Roca, piedra» — acuñado por Jesús para traducir el arameo Kēfā"},"paul":{"es":"«Pequeño, humilde»"},"thomas":{"es":"«Gemelo»"},"abraham":{"es":"«Padre de muchas naciones»"},"isaac":{"es":"«Él ríe» / «él reirá»"},"jacob":{"es":"«Suplantador», «el que sujeta el talón»"},"moses":{"es":"«Sacado de las aguas» (tradicional)"},"solomon":{"es":"«Paz» (de shalom)"},"matthew":{"es":"«Don de Yahvé»"},"adam":{"es":"«Hombre; humanidad», de adamah «tierra, suelo»"},"noah":{"es":"«Descanso, consuelo»"},"gabriel":{"es":"«Dios es mi fortaleza»"},"elijah":{"es":"«Mi Dios es Yahvé»"},"sarah":{"es":"«Princesa, mujer noble»"},"anna":{"es":"«Gracia, favor»"},"elizabeth":{"es":"«Mi Dios es un juramento»"},"omar":{"es":"«Longevo, floreciente, próspero»"},"aisha":{"es":"«Viva, llena de vida, próspera»"},"khadija":{"es":"«Nacida antes de tiempo, niña prematura»"},"abdullah":{"es":"«Siervo de Dios»"},"hassan":{"es":"\"Bueno, apuesto, hermoso\""},"husayn":{"es":"\"Pequeño Hasan\", \"el pequeño hermoso\""},"zaynab":{"es":"Una planta del desierto fragante y florida"},"nicholas":{"es":"\"Victoria del pueblo\""},"helen":{"es":"Incierto — probablemente \"antorcha, la resplandeciente\""},"catherine":{"es":"Incierto — vinculado por etimología popular a \"puro\""},"margaret":{"es":"\"Perla\""},"philip":{"es":"\"Amante de los caballos\""},"theodore":{"es":"\"Don de Dios\""},"anthony":{"es":"Un nombre gentilicio romano de origen incierto, quizá etrusco"},"julia":{"es":"\"Juvenil\"; forma femenina del nombre gentilicio Iulius, ligada a Júpiter"},"lakshmi":{"es":"\"Signo, marca\" → \"buena fortuna, prosperidad\""},"arjun":{"es":"\"Brillante, blanco, plateado, claro\""},"sita":{"es":"\"Surco\" (la línea trazada por el arado)"},"ganesh":{"es":"\"Señor de los ganas (huestes, tropas)\""},"priya":{"es":"\"Amada, querida\""}};
    var B = {"john":{"es":"Uno de los nombres más extendidos de la Tierra. El hebreo Yōḥānān, que llevaron John el Bautista y John el Apóstol, pasó al griego como Iōánnēs y al latín como Iohannes, y luego se difundió por toda la cristiandad. Europa occidental conservó la J/G inicial (John, Jean, Juan, Giovanni); el mundo eslavo oriental lo transformó en Ivan; y el Qurʼan conserva una forma árabe paralela, Yaḥyā, para el mismo profeta."},"mary":{"es":"El nombre de la madre de Jesús y de Miriam, la hermana de Moisés, y a través de ellas uno de los nombres femeninos más venerados del mundo. El griego Maria y el latín Maria lo difundieron por todas las lenguas cristianas; el Qurʼan da Maryam, la única mujer nombrada en él, de modo que el nombre es igual de central en el mundo islámico."},"muhammad":{"es":"El nombre del Profeta del islam y, según muchos recuentos, el nombre masculino más común de la Tierra. Del árabe muḥammad (raíz ḥ-m-d, «alabar») viajó con el islam a todas las lenguas del mundo musulmán, cada una remodelando sus sonidos: Mehmet en turco, Mohammad en persa/urdu, Muhamed en bosnio, Mamadou en África Occidental, Muhammad/Mohd en el Sudeste Asiático."},"alexander":{"es":"Llevado a tres continentes por Alexander Magno, cuyas conquistas plantaron el nombre desde Grecia hasta la India. Más tarde el cristianismo lo difundió aún más a través de santos y papas. Casi en todas partes se acorta con afecto — Alex, Sasha, Sander, Xander, Ale, Iskandar — e incluso entró en el mundo islámico como Iskandar/Sikandar."},"joseph":{"es":"El nombre del patriarca Joseph, vendido a Egipto, y de san Joseph, esposo de Mary. El hebreo Yōsēf pasó por el griego Iōsḗph y el latín Ioseph a todas las lenguas cristianas, contrayéndose en José en Iberia, Giuseppe en Italia y Josef en los mundos germánico y eslavo. El Qurʼan narra la historia del mismo patriarca bajo la forma árabe paralela Yūsuf, que se difundió con el islam desde África Occidental hasta Indonesia."},"michael":{"es":"Originalmente el nombre del arcángel Michael, el caudillo guerrero de las huestes celestiales, cuyo culto llevó el nombre por toda la cristiandad. El griego Michaḗl y el latín Michael se ramificaron en Michel, Miguel, Michele, Michael y el eslavo Mikhail, suavizando por el camino la gutural hebrea ḵ hasta un sonido k o h. El Qurʼan llama al mismo ángel Mīkāʼīl, dando una forma islámica paralela usada desde Irán hasta África Occidental."},"george":{"es":"Del griego Geōrgios, formado sobre geōrgós “labrador, trabajador de la tierra”, el nombre debe su vasto alcance a Saint George, el mártir matadragones venerado en toda la cristiandad y patrón de Inglaterra, Georgia y Etiopía. Se despliega en Jorge, Giorgio, Georg y Jerzy, y el mundo eslavo oriental lo dividió en dos nombres vivos — el culto Georgy y el cotidiano Yuri. En el Cáucaso es un favorito nacional: el georgiano Giorgi y el armenio Gevorg."},"sophia":{"es":"El griego sophía significa sencillamente “sabiduría”, personificada como virtud y consagrada en la gran iglesia de Hagia Sophia de Constantinopla, “Santa Sabiduría”. Llevado por la tradición bizantina y ortodoxa y portado por emperatrices y santas, se difundió como Sofia, Sophie, Zsófia y Zofia. Hoy es uno de los nombres de niña más populares del mundo, encabezando los registros de nacimientos por toda Europa y las Américas; el ruso le da el tierno diminutivo Sonya."},"fatima":{"es":"El nombre de Fāṭima al-Zahrāʼ, hija del Profeta Muhammad y esposa de ʿAlī, y por ello uno de los nombres femeninos más venerados del islam — sobre todo en la tradición chií, en la que es la madre de los imames. De la raíz árabe f-ṭ-m (“destetar”) se difundió con el islam y se fue suavizando por el camino: el turco lo recorta a Fatma, el persa redondea la terminación en Fāṭeme, y el sur y el sudeste asiáticos conservan la forma más plena Fatimah. En los Balcanes pervive como Fatima con el hipocorístico Fata."},"ali":{"es":"El nombre de ʿAlī ibn Abī Ṭālib, primo y yerno del Profeta Muhammad, cuarto califa en la tradición suní y primer imán del islam chií — lo que hace de Ali uno de los nombres centrales del mundo musulmán, y también uno de los “nombres hermosos”, pues al-ʿAlī es un atributo de Dios. Del árabe ʿAlī (raíz ʿ-l-w, “ser alto”), los sonidos se transmiten casi inalterados de una lengua a otra: Ali en turco y persa, Ali en urdu, Alija en bosnio, Aliyu en África Occidental. En Occidente se conoce sobre todo por el boxeador Muhammad Ali."},"krishna":{"es":"Krishna es el octavo avatar de Vishnú y una de las deidades más queridas del hinduismo: el vaquero flautista de Vrindavan y el sabio auriga del Bhagavad Gita. El sánscrito kṛṣṇa significa literalmente «oscuro, negro», en alusión a su tez, y dio lugar a formas cariñosas como Kanha y el tamil Kannan. Como nombre propio es común en toda la India y en toda la diáspora hindú; su difusión por el Sudeste Asiático se produjo a través del teatro de sombras wayang y el Mahabharata."},"rama":{"es":"Rama es un avatar de Vishnú y el héroe del Ramayana, el rey ideal de Ayodhya, cuya historia figura entre las más contadas del mundo. El sánscrito rāma significa \"agradable, encantador\". Ante todo fue la epopeya la que llevó el nombre por todo el Sudeste Asiático: los reyes tailandeses de la dinastía Chakri adoptan todos el nombre de reinado de Rama, la propia Ayutthaya recibió su nombre de Ayodhya, lugar de nacimiento de Rama, y Rama pervive en el Reamker camboyano (como Preah Ream), en el wayang javanés y balinés, y en el Phra Lak Phra Ram laosiano."},"david":{"es":"El nombre del rey pastor de Israel, segundo rey y vencedor de Goliat, venerado por igual en el judaísmo, el cristianismo y el islam. El hebreo Dāwīḏ pasó por el griego y el latín a todas las lenguas europeas casi sin cambios, mientras que el georgiano Davit y el etíope Dawit se convirtieron en nombres reales por derecho propio. Como David es también un profeta del Qurʼan, una línea islámica paralela discurre a través del árabe Dāwūd — Daud, Davut, Daudi — por todo el mundo musulmán."},"daniel":{"es":"Del profeta visionario del Libro de Daniel, cuya fe en el foso de los leones convirtió el nombre en sinónimo de firmeza. El hebreo Dāniyyēl pasó por el griego Daniḗl y el latín Daniel al Occidente cristiano, conservando una grafía notablemente estable, mientras que el mundo eslavo lo remodeló en Daniil y Danylo. Daniel es honrado también en la tradición islámica como el profeta Dāniyāl, cuya tumba en Susa sigue siendo lugar de peregrinación."},"peter":{"es":"El nombre que Jesús dio al pescador Simón — el griego Pétros, \"roca\", traducción del apodo arameo Kēfā —, haciéndolo la roca sobre la que se edificó la Iglesia. Como primer papa, san Pedro llevó el nombre a toda tierra cristiana: latín Petrus, francés Pierre, español Pedro, italiano Pietro, ruso Pyotr. Los cristianos orientales conservaron el griego Petros, y los cristianos de habla árabe dicen Buṭrus."},"paul":{"es":"El cognomen romano Paulus, «pequeño», que adoptó el apóstol Paul — nacido como Saul de Tarso — cuyas cartas dieron forma a la teología cristiana y llevaron su nombre por todo el mundo. Las iglesias de habla griega lo conocían como Paûlos, y del latín Paulus surgieron Pablo, Paolo, Paulo, Paweł y el eslavo Pavel. El armenio lo transformó de manera llamativa en Poġos, y los cristianos de habla árabe lo llaman Būlus."},"thomas":{"es":"El apodo del apóstol que dudó de la Resurrección hasta que tocó las llagas de Cristo — arameo Tʼōmā, «gemelo», que los Evangelios griegos también traducen como Dídymos. A través del griego Thōmâs y el latín Thomas se difundió por Occidente como Thomas, Tomás, Tommaso y Tomasz, mientras que el oriente eslavo lo remodeló en Foma y Khoma. Los cristianos de habla árabe conservan el sonido arameo como Tūmā."},"abraham":{"es":"El patriarca venerado como padre de los creyentes en las tres religiones abrahámicas. El hebreo Avraham, «padre de muchas naciones», pasó por el griego Abraám y el latín Abraham al Occidente cristiano, mientras que el Qurʼan ofrece la forma paralela Ibrāhīm — uno de los nombres masculinos más comunes en todo el mundo musulmán, de Marruecos a Indonesia. El neerlandés lo abrevia en Bram; el Cáucaso lo remodela como Ibragim."},"isaac":{"es":"El hijo de Abraham y segundo patriarca, cuyo nombre hebreo Yitzḥaq significa «él ríe». El griego Isaák y el latín Isaac lo llevaron a occidente — italiano Isacco, alemán y ruso Isaak —, mientras que el Qurʼan llama al mismo profeta Isḥāq. Favorito por igual entre familias judías, cristianas y musulmanas, lo han llevado figuras que van desde Isaac Newton hasta el escritor ruso Isaak Babel."},"jacob":{"es":"El tercer patriarca, más tarde rebautizado Israel; su nombre hebreo Yaʿaqov dio origen a uno de los árboles genealógicos más enmarañados de toda la onomástica. El latín Iacobus produjo Jacob, Jakob y el eslavo Yakov, pero una variante del latín vulgar, Iacomus, se desgajó para dar el italiano Giacomo, el francés Jacques, el inglés James y los ibéricos Diego, Santiago, Tiago y Jaime — todos dobletes de un mismo nombre. El Qurʼan conserva al profeta como Yaʻqūb."},"moses":{"es":"El profeta que sacó a los israelitas de Egipto; su nombre hebreo Mosheh se interpreta tradicionalmente como \"sacado de las aguas\". A través del griego Mōÿsês y el latín Moyses se difundió como Moses, el francés Moïse, el español Moisés y el italiano Mosè, mientras que Mūsā — mencionado en el Qurʼan más veces que cualquier otro profeta — se convirtió en uno de los grandes nombres del mundo musulmán, llevado por el emperador de Malí Mansa Musa."},"solomon":{"es":"El rey sabio, hijo de David; su nombre hebreo Shlomoh procede de shalom, \"paz\". El griego Solomṓn y el latín Salomon dieron Solomon, el francés Salomon, el italiano Salomone y el portugués Salomão. Los emperadores de Etiopía se proclamaron descendientes suyos en la dinastía salomónica, y el Qurʼan lo honra como el rey-profeta Sulaymān — origen del turco Süleyman, que llevó el más grande de los sultanes otomanos."},"matthew":{"es":"El nombre del apóstol y evangelista Matthew, el recaudador de impuestos llamado por Jesús y autor tradicional del primer Evangelio. El hebreo Mattityāhū (\"don de Yahvé\") se abrevió en griego como Maththaîos y se latinizó como Matthaeus, para luego extenderse por toda la cristiandad como Matteo, Mateo, Matthieu, Mateusz y el eslavo Matvei. Los cristianos de habla árabe conocen al evangelista como Mattā."},"adam":{"es":"El nombre del primer hombre, formado de la tierra en el Génesis y nombrado veinticinco veces en el Qurʼan, y por ello compartido por igual entre judíos, cristianos y musulmanes. De manera insólita, apenas necesita transformación al pasar de una lengua a otra — Adam en inglés, alemán, polaco y árabe, Adán en español, Adamo en italiano, Adem en turco y bosnio, Adamu en hausa y suajili. En el mundo islámico, Ādam es muy común como nombre de pila cotidiano."},"noah":{"es":"El constructor del arca que sobrevivió al Diluvio, honrado tanto en la Biblia como en el Qurʼan. El hebreo Nōaḥ pasó por el griego Nôe y el latín Noe hasta dar el romance Noé y el italiano Noè, mientras que el inglés conservó la forma más completa Noah. En el siglo veintiuno, Noah se ha disparado a lo más alto de las listas de nombres de niño en Estados Unidos y toda Europa, e incluso ha sido retomado en préstamo en Japón como el nombre moderno Noa. El Qurʼan narra la misma historia bajo la forma árabe paralela Nūḥ, uno de los cinco mayores profetas del islam."},"gabriel":{"es":"El nombre del arcángel que revela visiones a Daniel, anuncia el nacimiento de John y de Jesús y que en el islam dicta el Qurʼan a Muhammad. El hebreo Gaḇrīʼēl se convirtió en el griego Gabriḗl y el latín Gabriel, manteniéndose cercano a su origen en francés, español, portugués y alemán, suavizándose en el italiano Gabriele y en el eslavo Gavriil / Gavrilo. El Qurʼan llama al mismo ángel Jibrīl, y en Etiopía el arcángel Gabrʼel es profundamente venerado."},"elijah":{"es":"El nombre del ardiente profeta del siglo IX a. C. que se enfrentó a los sacerdotes de Baal en el monte Carmel y fue arrebatado al cielo en un torbellino. En el griego del Nuevo Testamento es Ēlías, que dio el latín Elias y las numerosas formas europeas Elias / Élie / Ilie, mientras que el mundo eslavo oriental lo convirtió en el cotidiano Ilya. La forma más completa, Elijah, se ha convertido en uno de los nombres ingleses modernos más destacados. El Qurʼan honra al mismo profeta bajo la forma árabe paralela Ilyās."},"sarah":{"es":"El nombre de la esposa del patriarca Abraham, a quien en el Génesis se le cambia el nombre de Sarai a Sarah, «princesa». El griego Sárra y el latín Sara lo llevaron por todo el mundo cristiano, donde se convirtió en uno de los nombres femeninos más populares de la era moderna. Como Abraham es un patriarca compartido, el mismo nombre pervive en el mundo musulmán como Sāra, y varía con afecto desde Zara hasta el finlandés Saara."},"anna":{"es":"Del hebreo Ḥannāh, la madre del profeta Samuel, un nombre que significa «gracia». El griego lo transcribió como Ánna —llevado en el Evangelio de Lucas por la profetisa Anna— y a través del latín se convirtió en uno de los nombres femeninos más extendidos de Europa, honrado además como el nombre de santa Anne, madre de la Virgen Mary. El inglés conserva tanto Anna, de origen griego, como Hannah, restaurado del hebreo, como un doblete, y la misma figura aparece en el islam como Ḥanna, la madre de Mary."},"elizabeth":{"es":"Del hebreo Elišévaʿ, la esposa de Aaron y, en el Evangelio de Lucas, la madre de John el Bautista. El griego Elisábet y el latín Elisabeth lo difundieron por la cristiandad, donde lo llevaron santos y una larga estirpe de reinas, sobre todo Elizabeth I y Elizabeth II de Inglaterra. En la península ibérica el mismo nombre se remodeló en un famoso vástago, Isabel (italiano Isabella), mientras que los mundos eslavo y húngaro le dieron Yelizaveta y Erzsébet."},"omar":{"es":"Llevado por ʿUmar ibn al-Khattāb, compañero del Profeta y segundo califa rāshidūn cuyo reinado dio forma al primer Estado islámico, ʿUmar es uno de los nombres masculinos clásicos del mundo musulmán. De la raíz árabe ʿ-m-r (“vivir, prosperar”) significa “longevo, próspero”. Se transformó en el turco Ömer y el bosnio Omer, y llegó a Occidente a través de figuras como Omar Sharif. Un nombre hebreo sin relación, Omar — un nieto de Esaú en el Génesis — es solo una coincidencia sonora aparte."},"aisha":{"es":"El nombre de ʿĀʼisha bint Abī Bakr, esposa del Profeta Muhammad célebre como erudita y transmisora de hadices, lo que lo ha convertido en uno de los nombres femeninos más populares de todo el mundo musulmán. De la raíz árabe ʿ-y-sh (“vivir”) significa “viva, con vida”. El turco lo transformó en Ayşe — durante mucho tiempo el nombre femenino más común de Turquía —, mientras que en el Magreb se usa Aïcha y en el sur de Asia Ayesha. En las últimas décadas también ha figurado ampliamente en Gran Bretaña, Francia y Estados Unidos."},"khadija":{"es":"Khadīja bint Khuwaylid fue la primera esposa del Profeta Muhammad, una rica comerciante mecana y la primera persona en abrazar el islam; desde entonces su nombre ha sido muy apreciado. Deriva de la raíz árabe kh-d-j, asociada a un niño “nacido temprano” o prematuro. El turco lo lleva como Hatice, África Occidental como el hausa Hadiza y el senegalés Khady, y el suajili como Hadija. Junto con Fatima y Aisha figura entre los nombres femeninos más comunes del mundo musulmán."},"abdullah":{"es":"Un nombre teofórico que significa “siervo de Dios”, formado por ʿabd (“siervo”) y Allāh. Fue el nombre del padre del Profeta Muhammad, ʿAbd Allāh ibn ʿAbd al-Muttalib, y un hadiz señala a ʿAbdullāh y ʿAbd al-Rahmān como los nombres más amados por Dios — por lo que figura entre los nombres más recomendados del islam. Recorre el mundo musulmán con leves cambios fonéticos: el persa Abdollah, los magrebíes Abdallah y Abdellah, el nigeriano Abdullahi, el africano occidental francófono Abdoulaye y el bosnio Abdulah."},"hassan":{"es":"Ḥasan (raíz ḥ-s-n, “ser bueno, hermoso”) era el nombre de Hasan ibn Ali, nieto mayor del Profeta Muhammad y segundo imam chií. Casi siempre se empareja con el nombre de su hermano menor — Hasan y Husayn juntos. Llevado por el islam por todo el mundo, conservó una forma notablemente estable (Hasan en turco, Hasan/Haso en bosnio) y sigue siendo uno de los nombres masculinos más comunes del mundo musulmán."},"husayn":{"es":"Ḥusayn es el diminutivo de Ḥasan — «pequeño Hasan», «el pequeño hermoso». Lo llevó Husayn ibn Ali, nieto menor del Profeta, cuyo martirio en la batalla de Kerbala en el año 680 d. C. convirtió el nombre en el corazón emocional del islam chií, conmemorado cada año en la Ashura. Sus formas recorren el mundo musulmán: el persa Hossein, el turco Hüseyin, el Hussain surasiático y el Hussein árabe que llevaron Saddam Hussein y el rey Hussein de Jordania."},"zaynab":{"es":"Zaynab es el nombre de una planta del desierto fragante y florida. Lo llevó una hija del Profeta Muhammad, Zaynab bint Muhammad, y su nieta Zaynab bint Ali, hermana de Husayn y venerada heroína de la tragedia de Kerbala. El nombre florece por todo el mundo musulmán, sobre todo como el turco Zeynep — durante años el nombre femenino más popular de Turquía — y como el africano occidental Zenabou."},"nicholas":{"es":"Del griego Nikólaos, «victoria del pueblo», difundido por toda la cristiandad gracias al culto de san Nicholas de Mira — el obispo del siglo IV cuya leyenda de los regalos se convirtió en Santa Claus, nombre a su vez desgastado del neerlandés Sinterklaas. Casi en todas partes se acorta con afecto: Klaus en alemán, Klaas en neerlandés, Nikos en griego, Kolya en ruso. Europa del Este lo remodeló en Nikolai, Mykola y Mikuláš, mientras que Hungría lo convirtió en Miklós."},"helen":{"es":"La forma inglesa del griego Helénē, probablemente de una palabra que significa «antorcha» o «la brillante». La llevó Helen de Troya, cuya belleza se dijo que había «hecho zarpar mil naves», y santa Helena, madre del emperador Constantine, a quien se atribuye el hallazgo de la Vera Cruz. A través del latín Helena se convirtió en Elena por los mundos románico y eslavo meridional y en Yelena / Olena en el este, mientras que el húngaro la remodeló en Ilona."},"catherine":{"es":"Del griego Aikaterínē, pronto vinculado por etimología popular a katharós, «puro», lo que fijó la grafía con -th- en Occidente. Difundido por el culto sumamente popular a santa Catherine de Alejandría, se convirtió en uno de los nombres femeninos más usados de Europa, llevado por reinas y emperatrices, de Catherine de Medici a Catherine la Grande. Se acorta en todo un guardarropa de hipocorísticos — Kate, Katie, Katya, Kasia — uno de los cuales, el Karin alemán y sueco, es homófono de un nombre de niña japonés."},"margaret":{"es":"Del griego margarítēs (\"perla\"), palabra que el propio griego había tomado prestada de un Oriente más lejano. El culto a santa Margarita de Antioquía lo hizo predilecto en toda la Europa medieval, llevado más tarde por reinas y por figuras que van de Margaret Thatcher a Margaret Atwood. Sus hipocorísticos cobraron vida propia — el alemán Greta, el italiano y español Rita, y el inglés Daisy, ya que el francés marguerite pasó a nombrar la flor."},"philip":{"es":"Del griego Phílippos (\"amante de los caballos\"), nombre de la realeza macedonia que llevó Philip II, padre de Alejandro Magno. Como nombre de un apóstol se difundió por toda la cristiandad y se volvió predilecto de los reyes ibéricos — seis Felipe españoles y varios Filipe portugueses, de quienes toman nombre las Filipinas. Los británicos lo conocen sobre todo por Prince Philip, el difunto duque de Edimburgo."},"theodore":{"es":"Del griego Theódōros (\"don de Dios\"), imagen especular de Dorotea. Llevado por muchos santos de los primeros tiempos, arraigó por toda Europa y más allá — el ruso Fyodor de Dostoyevski y el etíope Tewodros. En inglés encanta a través de sus diminutivos Ted, Teddy y Theo."},"anthony":{"es":"Del nombre gentilicio romano Antōnius, una antigua gens quizá de origen etrusco cuyo miembro más tristemente célebre fue Mark Antony (Marcus Antōnius). Los muchos santos llamados Anthony — sobre todo Antonio el Grande y Antonio de Padua — lo llevaron por la cristiandad, donde Antonio se convirtió en uno de los nombres más comunes de Italia y de la península ibérica. La grafía con h refleja una posterior y errónea asociación con el griego ánthos (\"flor\")."},"julia":{"es":"El femenino del nombre gentilicio romano Iūlius, la familia de Julio César y del emperador Augusto, lo que hizo de Iūlia uno de los grandes nombres de la dinastía julio-claudia — tanto la hija de César como la hija de Augusto se llamaban Julia. Durante mucho tiempo también nombre de una santa cristiana, es hoy uno de los nombres de niña más populares de Europa y América. Su equivalente masculino pervive como Julius, Julio y Jules."},"lakshmi":{"es":"Lakshmi es la diosa hindú de la riqueza, la fortuna y la belleza, y la consorte de Vishnu, junto a cada uno de cuyos avatares adopta una forma acorde. El sánscrito lakṣmī deriva de lakṣ «marcar, percibir», de donde el sentido de un signo auspicioso y, por extensión, de prosperidad. Se la venera sobre todo en Diwali, y su nombre es uno de los nombres femeninos más comunes en todo el sur de la India, aunque compuestos como Lakshmi Narayan y apellidos como Mittal también lo llevan los hombres. En Bengala tanto la diosa como el nombre se pronuncian Lokkhi."},"arjun":{"es":"Arjuna es el héroe-arquero del Mahabharata — el tercero de los cinco hermanos Pandava, hijo del dios Indra y el guerrero a quien Krishna transmite el Bhagavad Gita en el campo de batalla de Kurukshetra. El sánscrito arjuna significa «brillante, plateado, blanco». En la forma Arjun es uno de los nombres masculinos más populares de la India actual, y la epopeya llevó al personaje por todo el Sudeste Asiático, donde el refinado ksatriya Arjuna (Janaka en javanés) es un favorito del teatro de sombras wayang."},"sita":{"es":"Sita es la heroína del Ramayana y la esposa de Rama, un avatar de Lakshmi y el ideal mismo de la virtud, la devoción y la constancia. Su nombre sánscrito significa «surco»: el rey Janaka la encontró en un campo arado, hija de la diosa de la tierra Bhumi. La epopeya la difundió por todo el Sudeste Asiático — es Nang Sida (นางสีดา) en el Ramakien tailandés, Sinta o Shinta en el wayang javanés, y Neang Seda en el Reamker camboyano."},"ganesh":{"es":"Ganesha es el hijo con cabeza de elefante de Shiva y Parvati, el querido removedor de obstáculos y patrón de los comienzos, el saber y las artes, invocado antes de toda nueva empresa. Su nombre sánscrito une gaṇa «huestes, tropas» con īśa «señor», y se le conoce igualmente como Vinayaka y Ganapati. En la forma Ganesh es un nombre masculino común en la India, y la deidad se difundió por todo el Sudeste Asiático — venerada en Tailandia como Phra Phikhanet (พระพิฆเนศ), patrón de las artes, y en Indonesia como Ganesha, cuya imagen es el emblema del Instituto Tecnológico de Bandung (ITB)."},"priya":{"es":"Priya no es un nombre de divinidad, sino un nombre propio sin más — el femenino del sánscrito priya «amado, querido», de la raíz prī «agradar». Es uno de los nombres femeninos más comunes hoy en toda la India, Nepal, Bangladés y Sri Lanka, y llega con facilidad a la diáspora como una forma simpática y fácil de pronunciar. En tamil, el masculino Priyan o Priya también se usa para varones. La raíz es antigua: está emparentada con el nombre de la diosa germánica Frigg, ambos del protoindoeuropeo *priH- «amado»."}};
